class Player:
    teamName = '皇马'  # 类变量

    def __init__(self, name):
        self.name = name  # 创建实例变量

    @classmethod
    def getTeamName(cls): # 类方法，第一个参数为cls，即类本身
        return cls.teamName  # 通过cls 访问类变量 


print(Player.getTeamName()) #调用类方法

class Player:
    teamName = '皇马'  # 类变量

    def __init__(self, name):
        self.name = name  # 实例变量

    @staticmethod
    def demo(): # 静态方法，注意没有什么self 或 cls 参数
        print("I am a static method.")


p1 = Player('C罗')
p1.demo()          # 对象调用 静态方法
Player.demo()      # 类调用 静态方法

class BodyInfo:

    @staticmethod
    def bmi(weight, height):
        # 静态方法
        return weight / (height**2)


weight = 75
height = 1.8
print(BodyInfo.bmi(weight, height))  # 类直接调用静态方法
